#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Linq;
using PVZEngine;

namespace MVZ2.Vanilla.Saves
{
    public class TeleporterTeam
    {
        public TeleporterTeam() : base()
        {
        }
        public TeleporterTeam Clone()
        {
            var newTeam = new TeleporterTeam();
            foreach (var pair in tiles)
            {
                var tile = pair.Value;
                newTeam.tiles.Add(pair.Key, tile.Clone());
            }
            return newTeam;
        }
        public int[] GetTileIndexes()
        {
            return tiles.Keys.ToArray();
        }
        public TeleporterTeamTile? GetTile(int index)
        {
            return tiles.TryGetValue(index, out var tile) ? tile : null;
        }
        public void AddTileEntity(int index, NamespaceID entityID)
        {
            var tile = GetTile(index);
            if (tile == null)
            {
                tile = new TeleporterTeamTile();
                tiles.Add(index, tile);
            }
            tile.AddEntity(entityID);
        }
        public void RemoveTileEntity(int index, NamespaceID entityID)
        {
            var tile = GetTile(index);
            if (tile == null)
                return;
            tile.RemoveEntity(entityID);
        }
        public void ClearTile(int index)
        {
            var tile = GetTile(index);
            if (tile == null)
                return;
            tile.ClearEntities();
        }
        public SerializableTeleporterTeam ToSerializable()
        {
            var tileArray = tiles.Select(t => new SerializableTeleporterTeamTile() { index = t.Key, entities = t.Value.GetEntities() }).ToArray();
            return new SerializableTeleporterTeam()
            {
                tiles = tileArray
            };
        }
        public static TeleporterTeam FromSerializable(SerializableTeleporterTeam seri)
        {
            var team = new TeleporterTeam();
            if (seri.tiles != null)
            {
                foreach (var tile in seri.tiles)
                {
                    if (tile == null)
                        continue;
                    team.tiles.Add(tile.index, TeleporterTeamTile.FromSerializable(tile));
                }
            }
            return team;
        }
        private readonly Dictionary<int, TeleporterTeamTile> tiles = new Dictionary<int, TeleporterTeamTile>();
    }
    public class TeleporterTeamTile
    {
        public TeleporterTeamTile() : base()
        {
        }
        public TeleporterTeamTile Clone()
        {
            var newTile = new TeleporterTeamTile();
            foreach (var ent in entities)
            {
                newTile.entities.Add(ent);
            }
            return newTile;
        }
        public void AddEntity(NamespaceID id)
        {
            entities.Add(id);
        }
        public void RemoveEntity(NamespaceID id)
        {
            entities.Remove(id);
        }
        public void ClearEntities()
        {
            entities.Clear();
        }
        public NamespaceID[] GetEntities()
        {
            return entities.ToArray();
        }
        public SerializableTeleporterTeamTile ToSerializable()
        {
            var tileArray = entities.ToArray();
            return new SerializableTeleporterTeamTile()
            {
                entities = tileArray
            };
        }
        public static TeleporterTeamTile FromSerializable(SerializableTeleporterTeamTile seri)
        {
            var tile = new TeleporterTeamTile();
            if (seri.entities != null)
            {
                foreach (var entity in seri.entities)
                {
                    if (!NamespaceID.IsValid(entity))
                        continue;
                    tile.entities.Add(entity);
                }
            }
            return tile;
        }
        private readonly List<NamespaceID> entities = new List<NamespaceID>();
    }
    [Serializable]
    public class SerializableTeleporterTeam
    {
        public SerializableTeleporterTeamTile?[]? tiles;
    }
    [Serializable]
    public class SerializableTeleporterTeamTile
    {
        public int index;
        public NamespaceID?[]? entities;
    }
}
